import awkward as ak
from pocket_coffea.lib.weights.weights import WeightLambda


def _toy_reweight(params, metadata, events, size, shape_variation):
    nominal = events.LHEWeight_originalXWGTUP / ak.mean(events.LHEWeight_originalXWGTUP)
    up = nominal * 1.05
    down = nominal * 0.95
    return nominal, up, down


toy_reweight = WeightLambda.wrap_func(
    name="toy_reweight",
    function=_toy_reweight,
    has_variations=True,
)

# Registering the custom weight class in a PocketCoffea configuration:
weights_classes = [toy_reweight]

weights = {
    "common": {
        "inclusive": ["genWeight", "lumi", "XS", "toy_reweight"],
    },
}
